"""Keep CLI/server identity rules and SQL entity data consistent without a third wheel."""

import argparse
from html.entities import html5
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]


def generated_files():
    source = (
        "# Generated by scripts/sync-identity-contract.py; edit contracts/identity.py.\n"
        + (ROOT / "contracts/identity.py").read_text()
    )
    entities = ",\n".join(
        "('%s', '%s')" % (name.replace("'", "''"), value.replace("'", "''"))
        for name, value in sorted(html5.items())
    )
    expansions = ",\n".join(
        "('%s', '%s')" % (char.replace("'", "''"), char.upper().replace("'", "''"))
        for char in map(chr, range(32, 65536))
        if len(char.upper()) > 1
    )
    return {
        ROOT / "src/netvault/identity_shared.py": source,
        ROOT / "packages/netvault-server/src/netvault_server/identity_shared.py": source,
        ROOT
        / "packages/netvault-server/src/netvault_server/server/data/html_entities.sql": "-- Generated HTML5 entity data for the shared normalization contract.\n"
        "CREATE TABLE IF NOT EXISTS netvault_html_entities (name TEXT PRIMARY KEY, replacement TEXT NOT NULL);\n"
        "INSERT INTO netvault_html_entities (name,replacement) VALUES\n" + entities + "\n"
        "ON CONFLICT (name) DO UPDATE SET replacement=excluded.replacement;\n"
        "CREATE TABLE IF NOT EXISTS netvault_upper_expansions (character TEXT PRIMARY KEY, replacement TEXT NOT NULL);\n"
        "INSERT INTO netvault_upper_expansions (character,replacement) VALUES\n" + expansions + "\n"
        "ON CONFLICT (character) DO UPDATE SET replacement=excluded.replacement;\n",
    }


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    different = []
    for path, content in generated_files().items():
        if args.check:
            if not path.exists() or path.read_text() != content:
                different.append(str(path.relative_to(ROOT)))
        else:
            path.write_text(content)
    if different:
        raise SystemExit("Identity contract files need regeneration: " + ", ".join(different))
    print("Identity contract copies and SQL entity data are consistent.")


if __name__ == "__main__":
    main()
